CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE UNIQUE INDEX IF NOT EXISTS customer_phone ON customers(json_extract(data,'$.phone'));
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS warehouses(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS drivers(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), product_id TEXT NOT NULL REFERENCES products(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES order_items(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS allocations(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), invoice_id TEXT NOT NULL REFERENCES invoices(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS purchases(id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS purchase_items(id TEXT PRIMARY KEY, purchase_id TEXT NOT NULL REFERENCES purchases(id), product_id TEXT NOT NULL REFERENCES products(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY, purchase_id TEXT NOT NULL REFERENCES purchases(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS bills(id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS supplier_payments(id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS supplier_allocations(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES supplier_payments(id), bill_id TEXT NOT NULL REFERENCES bills(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS trips(id TEXT PRIMARY KEY, driver_id TEXT NOT NULL REFERENCES drivers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS stops(id TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id), item_id TEXT NOT NULL REFERENCES order_items(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS proofs(id TEXT PRIMARY KEY, stop_id TEXT NOT NULL REFERENCES stops(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS cash(id TEXT PRIMARY KEY, stop_id TEXT NOT NULL REFERENCES stops(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS returns(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES order_items(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE UNIQUE INDEX IF NOT EXISTS message_event_key ON messages(json_extract(data,'$.eventKey'));
CREATE TABLE IF NOT EXISTS executions(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS audits(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS idempotency(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, request TEXT NOT NULL, response TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS orders_customer ON orders(customer_id);
CREATE INDEX IF NOT EXISTS items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS stock_product ON movements(product_id,warehouse_id);
CREATE INDEX IF NOT EXISTS stops_trip ON stops(trip_id);
CREATE INDEX IF NOT EXISTS messages_customer ON messages(customer_id);
CREATE TRIGGER IF NOT EXISTS immutable_stock_update BEFORE UPDATE ON movements BEGIN SELECT RAISE(ABORT,'Stock movements are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_stock_delete BEFORE DELETE ON movements BEGIN SELECT RAISE(ABORT,'Stock movements are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_audit_update BEFORE UPDATE ON audits BEGIN SELECT RAISE(ABORT,'Audit entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_audit_delete BEFORE DELETE ON audits BEGIN SELECT RAISE(ABORT,'Audit entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS finalized_invoice_identity BEFORE UPDATE ON invoices WHEN json_extract(NEW.data,'$.amount') != json_extract(OLD.data,'$.amount') OR json_extract(NEW.data,'$.items') != json_extract(OLD.data,'$.items') OR json_extract(NEW.data,'$.businessName') != json_extract(OLD.data,'$.businessName') OR json_extract(NEW.data,'$.date') != json_extract(OLD.data,'$.date') BEGIN SELECT RAISE(ABORT,'Finalized invoice charges and identity are immutable'); END;
INSERT OR IGNORE INTO migrations VALUES(1,datetime('now'));
